    {
        return fa_num(round($bytes / 1048576)) . ' مگابایت';
    }

    private static function min(int $sec): string
    {
        return $sec % 3600 === 0 ? fa_num($sec / 3600) . ' ساعت' : fa_num((int) round($sec / 60)) . ' دقیقه';
    }

